  `article_id` varchar(10) NOT NULL,
  `devise_id` bigint DEFAULT NULL,
  `entree_id` bigint NOT NULL,
  `devise_reference_id` bigint DEFAULT NULL,
  `montant_reference` decimal(14,5) NOT NULL,
  `taux_change` decimal(20,8) DEFAULT NULL,
  `conditionnement_id` bigint DEFAULT NULL,
  `prix_achat_conditionnement` decimal(10,5) DEFAULT NULL,
  `prix_achat_unitaire_base` decimal(10,5) DEFAULT NULL,
  `prix_vente_conditionnement` decimal(10,5) DEFAULT NULL,
  `prix_vente_unitaire_base` decimal(10,5) DEFAULT NULL,
  `quantite_base` decimal(12,5) DEFAULT NULL,
  `quantite_saisie` decimal(12,5) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `stock_ligneentree_devise_id_2d1d5e04_fk_stock_devise_id` (`devise_id`),
  KEY `stock_ligneentree_entree_id_c3061fbb_fk_stock_entree_id` (`entree_id`),
  KEY `stock_ligne_article_e99d66_idx` (`article_id`,`date_entree`),
  KEY `stock_ligneentree_devise_reference_id_87f7ab70_fk_stock_dev` (`devise_reference_id`),
  KEY `stock_ligneentree_conditionnement_id_bf6e8ddc_fk_stock_con` (`conditionnement_id`),
  CONSTRAINT `stock_ligneentree_article_id_5e64e8c1_fk_stock_art` FOREIGN KEY (`article_id`) REFERENCES `stock_article` (`article_id`),
  CONSTRAINT `stock_ligneentree_conditionnement_id_bf6e8ddc_fk_stock_con` FOREIGN KEY (`conditionnement_id`) REFERENCES `stock_conditionnementarticle` (`id`),
  CONSTRAINT `stock_ligneentree_devise_id_2d1d5e04_fk_stock_devise_id` FOREIGN KEY (`devise_id`) REFERENCES `stock_devise` (`id`),
  CONSTRAINT `stock_ligneentree_devise_reference_id_87f7ab70_fk_stock_dev` FOREIGN KEY (`devise_reference_id`) REFERENCES `stock_devise` (`id`),
  CONSTRAINT `stock_ligneentree_entree_id_c3061fbb_fk_stock_entree_id` FOREIGN KEY (`entree_id`) REFERENCES `stock_entree` (`id`)
