--
-- Table structure for table `stock_requisitionligne`
--

DROP TABLE IF EXISTS `stock_requisitionligne`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `stock_requisitionligne` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `type_ligne` varchar(16) NOT NULL,
  `designation` varchar(255) NOT NULL,
  `quantite` decimal(12,5) NOT NULL,
  `unite` varchar(100) NOT NULL,
  `prix_estime` decimal(14,5) DEFAULT NULL,
  `prix_source` varchar(20) NOT NULL,
  `remarque` longtext NOT NULL,
  `ordre` int unsigned NOT NULL,
  `statut_stock` varchar(32) NOT NULL,
  `stock_actuel` decimal(12,5) DEFAULT NULL,
  `seuil_alerte` decimal(12,5) DEFAULT NULL,
  `article_id` varchar(10) DEFAULT NULL,
  `requisition_id` bigint NOT NULL,
  `conditionnement_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `stock_requi_requisi_dba78b_idx` (`requisition_id`,`ordre`),
  KEY `stock_requi_requisi_95ed46_idx` (`requisition_id`,`article_id`),
  KEY `stock_requisitionlig_article_id_1ce4358c_fk_stock_art` (`article_id`),
  KEY `stock_requisitionlig_conditionnement_id_00323cb6_fk_stock_con` (`conditionnement_id`),
  CONSTRAINT `stock_requisitionlig_article_id_1ce4358c_fk_stock_art` FOREIGN KEY (`article_id`) REFERENCES `stock_article` (`article_id`),
  CONSTRAINT `stock_requisitionlig_conditionnement_id_00323cb6_fk_stock_con` FOREIGN KEY (`conditionnement_id`) REFERENCES `stock_conditionnementarticle` (`id`),
  CONSTRAINT `stock_requisitionlig_requisition_id_70ed2d1f_fk_stock_req` FOREIGN KEY (`requisition_id`) REFERENCES `stock_requisition` (`id`),
  CONSTRAINT `stock_requisitionligne_chk_1` CHECK ((`ordre` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=657 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

